const listPublicScripts = `-- name: ListPublicScripts :many
SELECT
    s.id AS script_id,
    s.owner_user_id,
    s.title,
    s.summary,
    s.game_type,
    s.cover_asset_uri,
    s.language,
    s.content_rating,
    s.min_players,
    s.max_players,
    s.duration_minutes,
    s.difficulty,
    sv.id AS script_version_id,
    sv.version_no,
    sv.schema_version,
    s.created_at,
    s.updated_at
FROM scripts s
JOIN script_versions sv ON sv.id = s.published_version_id
JOIN script_publications p
  ON p.script_id = s.id
 AND p.script_version_id = sv.id
 AND p.channel = 'public'
 AND p.status = 'active'
WHERE s.deleted_at IS NULL
  AND s.status = 'published'
  AND sv.status = 'published_public'
  AND sv.validation_status IN ('passed', 'warning')
  AND (? = '' OR s.title LIKE CONCAT('%', ?, '%'))
  AND (? = '' OR s.game_type = ?)
  AND (? = 0 OR s.min_players >= ?)
  AND (? = 0 OR s.max_players <= ?)
  AND (? = 0 OR s.duration_minutes <= ?)
  AND (? = '' OR s.difficulty = ?)
  AND (? = '' OR s.id < ?)
ORDER BY s.id DESC
LIMIT ?
`

type ListPublicScriptsParams struct {
	Column1         interface{} `json:"column_1"`
	CONCAT          interface{} `json:"CONCAT"`
	Column3         interface{} `json:"column_3"`
	GameType        string      `json:"game_type"`
	Column5         interface{} `json:"column_5"`
	MinPlayers      uint8       `json:"min_players"`
	Column7         interface{} `json:"column_7"`
	MaxPlayers      uint8       `json:"max_players"`
	Column9         interface{} `json:"column_9"`
	DurationMinutes uint16      `json:"duration_minutes"`
	Column11        interface{} `json:"column_11"`
	Difficulty      string      `json:"difficulty"`
	Column13        interface{} `json:"column_13"`
	ID              string      `json:"id"`
	Limit           int32       `json:"limit"`
}

type ListPublicScriptsRow struct {
	ScriptID        string         `json:"script_id"`
	OwnerUserID     string         `json:"owner_user_id"`
	Title           string         `json:"title"`
	Summary         sql.NullString `json:"summary"`
	GameType        string         `json:"game_type"`
	CoverAssetUri   sql.NullString `json:"cover_asset_uri"`
	Language        string         `json:"language"`
	ContentRating   string         `json:"content_rating"`
	MinPlayers      uint8          `json:"min_players"`
	MaxPlayers      uint8          `json:"max_players"`
	DurationMinutes uint16         `json:"duration_minutes"`
	Difficulty      string         `json:"difficulty"`
	ScriptVersionID string         `json:"script_version_id"`
	VersionNo       uint32         `json:"version_no"`
	SchemaVersion   string         `json:"schema_version"`
	CreatedAt       time.Time      `json:"created_at"`
	UpdatedAt       time.Time      `json:"updated_at"`
}

func (q *Queries) ListPublicScripts(ctx context.Context, arg ListPublicScriptsParams) ([]ListPublicScriptsRow, error) {
	rows, err := q.query(ctx, q.listPublicScriptsStmt, listPublicScripts,
		arg.Column1,
		arg.CONCAT,
		arg.Column3,
		arg.GameType,
		arg.Column5,
		arg.MinPlayers,
		arg.Column7,
		arg.MaxPlayers,
		arg.Column9,
		arg.DurationMinutes,
		arg.Column11,
		arg.Difficulty,
		arg.Column13,
		arg.ID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPublicScriptsRow{}
	for rows.Next() {
		var i ListPublicScriptsRow
		if err := rows.Scan(
			&i.ScriptID,
			&i.OwnerUserID,
			&i.Title,
			&i.Summary,
			&i.GameType,
			&i.CoverAssetUri,
			&i.Language,
			&i.ContentRating,
			&i.MinPlayers,
			&i.MaxPlayers,
			&i.DurationMinutes,
			&i.Difficulty,
			&i.ScriptVersionID,
			&i.VersionNo,
			&i.SchemaVersion,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

